INSERT INTO `support_faqs_i18n` (`faq_id`, `locale`, `question`, `answer`)
VALUES
  ('66666666-6666-4666-8666-666666666661', 'tr', 'PaketJet nedir?', 'PaketJet, sehirler arasi hareket eden tasiyicilar ile gonderi sahiplerini ayni platformda bulusturan bir P2P kargo pazaryeridir. Kullanici aktif ilanlari inceleyip uygun kapasiteyi rezerve edebilir.'),
  ('66666666-6666-4666-8666-666666666662', 'tr', 'Nasil kargo gonderebilirim?', 'Ilanlar sayfasina girip guzergah, tarih ve kapasite filtreleriyle uygun secenegi bulun. Ardindan ilan detayini inceleyip rezervasyon surecini tamamlayin.'),
  ('66666666-6666-4666-8666-666666666663', 'tr', 'Tasiyici nasil olurum?', 'Uye olurken tasiyici rolunu secebilir veya ilgili panel alanindan tasiyici surecini tamamlayabilirsiniz. Daha sonra guzergah, tarih ve kapasite bilgileriyle ilan yayinlayabilirsiniz.'),
  ('66666666-6666-4666-8666-666666666664', 'tr', 'Odeme nasil yapilir?', 'Odeme akisi platform tarafindan yonetilir. Kullanici, rezervasyon asamasinda gosterilen yontemlerle islemi tamamlar ve islem kaydi sistemde tutulur.'),
  ('66666666-6666-4666-8666-666666666665', 'tr', 'Kargo takibi nasil yapilir?', 'Rezervasyon ve kullanici paneli ekranlarinda tasima surecinin guncel durumu gorulebilir. Gerektiginde destek ekibi de kayitlar uzerinden yardimci olur.'),
  ('66666666-6666-4666-8666-666666666666', 'tr', 'Hesabimi nasil silebilirim?', 'Hesap kapatma talebinizi destek ekibine iletebilirsiniz. Yasal saklama yukumluluklari disindaki veriler surec sonunda uygun sekilde kapatilir veya anonimlestirilir.'),
  ('66666666-6666-4666-8666-666666666667', 'tr', 'PaketJet hangi sehirlerde kullanilabilir?', 'Platform Turkiye geneli rota planlamasini destekler. Kullanici sehir listesi 81 ili kapsar; aktif ilan sayisi ise doneme gore degisebilir.'),
  ('66666666-6666-4666-8666-666666666668', 'tr', 'Ayni gun teslimat garanti edilir mi?', 'Hayir. Ilanlarda belirtilen tarih ve rota bilgisi tasiyicinin planina dayanir. Hizmet seklimiz esnek kapasite eslestirmesi oldugu icin teslim penceresi ilan bazinda degerlendirilmelidir.'),
  ('66666666-6666-4666-8666-666666666669', 'tr', 'Rezervasyon iptal edilirse ne olur?', 'Iptal zamani ve tasima asamasi belirleyicidir. Tasima baslamadan onceki iptaller ile tasima sirasindaki iptaller farkli kosullarla incelenebilir.'),
  ('66666666-6666-4666-8666-666666666670', 'tr', 'Siteye giris yapamiyorsam ne yapmaliyim?', 'Once sifremi unuttum akisini deneyin. Sorun devam ederse destek formundan e-posta adresinizi ve aldiginiz hata mesajini paylasin.'),
  ('66666666-6666-4666-8666-666666666671', 'tr', 'Telefon numarami degistirebilir miyim?', 'Evet. Profil bilgileri ekranindan iletisim verilerinizi guncelleyebilirsiniz. Baz i degisikliklerde guvenlik amacli ek dogrulama istenebilir.'),
  ('66666666-6666-4666-8666-666666666672', 'tr', 'Destek talebime ne kadar surede donus yapilir?', 'Talebin icerigine gore sure degisebilir; ancak ekip temel operasyonel konularda mumkun olan en kisa surede donus yapmayi hedefler.'),
  ('66666666-6666-4666-8666-666666666673', 'tr', 'Tasiyici paketi teslim alirken neyi kontrol eder?', 'Paket sayisi, genel fiziksel durum, agirlik ve beyan edilen icerik sinifi kontrol edilebilir. Uygun gorulmeyen veya eksik beyanli gonderi reddedilebilir.'),
  ('66666666-6666-4666-8666-666666666674', 'tr', 'Ek ucret cikabilir mi?', 'Beyan edilen agirlik ile gercek agirlik arasinda anlamli fark bulunmasi, ek bekleme ya da ikinci teslimat denemesi gibi durumlarda olay bazli ek maliyet degerlendirmesi yapilabilir.'),
  ('66666666-6666-4666-8666-666666666675', 'tr', 'Tarayicida sayfa hatasi alirsam ne yapmaliyim?', 'Tarayici onbellegini temizleyip tekrar deneyin. Sorun surerse kullandiginiz cihaz, tarayici ve hata goruntusu ile destek ekibine ulasin.'),
  ('66666666-6666-4666-8666-666666666676', 'tr', 'Yasakli urunleri nerede gorebilirim?', 'Tasima Kurallari sayfasi, platform uzerinden tasinamayacak urunler ile paketleme ve sorumluluk ilkelerini detayli olarak aciklar.')
ON DUPLICATE KEY UPDATE
  `question` = VALUES(`question`),
  `answer` = VALUES(`answer`);
